function toUint8Array(v: unknown): Uint8Array | undefined {
  if (v instanceof Uint8Array) return v;
  if (Array.isArray(v)) return new Uint8Array(v);
  if (v !== null && typeof v === 'object') return new Uint8Array(Object.values(v));
  return undefined;
}
// apply at receive boundary for every bytes-carrying provider
